        (CASE WHEN tiernotices->'free_tier'->>'Promo_Note' IS NOT NULL THEN 1 ELSE 0 END +
         CASE WHEN tiernotices->'member_tier'->>'Promo_Note' IS NOT NULL THEN 1 ELSE 0 END) AS total_promo_notes
    FROM promo_info
) sub WHERE total_promo_notes > 0;

