args.sql:
SELECT COUNT(*) FROM (
    SELECT p.content_key,
        CASE WHEN EXISTS (
            SELECT 1 FROM jsonb_each_text(p.tiernotices->'free_tier') WHERE value IS NOT NULL
        ) THEN 1 ELSE 0 END +
        CASE WHEN EXISTS (
            SELECT 1 FROM jsonb_each_text(p.tiernotices->'member_tier') WHERE value IS NOT NULL
        ) THEN 1 ELSE 0 END AS total_promotional_notes
    FROM promo_info p
) sub WHERE total_promotional_notes > 0;

SELECT COUNT(*) FROM (
    SELECT p.content_key,
        CASE WHEN EXISTS (
            SELECT 1 FROM jsonb_each_text(p.tiernotices->'free_tier') WHERE value IS NOT NULL
        ) THEN 1 ELSE 0 END +
        CASE WHEN EXISTS (
            SELECT 1 FROM jsonb_each_text(p.tiernotices->'member_tier') WHERE value IS NOT NULL
        ) THEN 1 ELSE 0 END AS total_promotional_notes
    FROM promo_info p
) sub GROUP BY total_promotional_notes;

SELECT COUNT(*) FROM (
    SELECT p.content_key,
        (SELECT COUNT(*) FROM jsonb_each(p.tiernotices->'free_tier') WHERE value IS NOT NULL AND value != 'null') +
        (SELECT COUNT(*) FROM jsonb_each(p.tiernotices->'member_tier') WHERE value IS NOT NULL AND value != 'null') AS total_promo_notes
    FROM promo_info p
) sub WHERE total_promo_notes > 0;

SELECT COUNT(*) FROM (
    SELECT p.content_key,
        (SELECT COUNT(*) FROM jsonb_each_text(p.tiernotices->'free_tier') WHERE value IS NOT NULL AND value != '') +
        (SELECT COUNT(*) FROM jsonb_each_text(p.tiernotices->'member_tier') WHERE value IS NOT NULL AND value != '') AS total_promo_notes
    FROM promo_info p
) sub WHERE total_promo_notes > 0;

SELECT COUNT(*) FROM (
    SELECT p.content_key,
        (SELECT COUNT(*) FROM jsonb_each(p.tiernotices->'free_tier') WHERE value IS NOT NULL) +
        (SELECT COUNT(*) FROM jsonb_each(p.tiernotices->'member_tier') WHERE value IS NOT NULL) AS total_promo_notes
    FROM promo_info p
) sub GROUP BY total_promo_notes;

SELECT COUNT(*) FROM (
    SELECT p.content_key,
        (SELECT COUNT(*) FROM jsonb_each(p.tiernotices->'free_tier')) +
        (SELECT COUNT(*) FROM jsonb_each(p.tiernotices->'member_tier')) AS total_promo_notes
    FROM promo_info p
) sub GROUP BY total_promo_notes;

SELECT COUNT(*) FROM (
    SELECT p.content_key,
        SUM(
            CASE WHEN p.tiernotices->'free_tier'->>'Promo_Note' IS NOT NULL THEN 1 ELSE 0 END +
            CASE WHEN p.tiernotices->'member_tier'->>'Promo_Note' IS NOT NULL THEN 1 ELSE 0 END
        ) AS total_promotional_notes
    FROM promo_info p
    GROUP BY p.content_key
    HAVING SUM(
        CASE WHEN p.tiernotices->'free_tier'->>'Promo_Note' IS NOT NULL THEN 1 ELSE 0 END +
        CASE WHEN p.tiernotices->'member_tier'->>'Promo_Note' IS NOT NULL THEN 1 ELSE 0 END
    ) > 0
) sub;
